{
  "references": [
    {
      "id": "R1",
      "summary_ko": "유리잔이 사라지고 창문을 닦기 시작함."
    },
    {
      "id": "R2",
      "summary_ko": "물잔이 사라진 후 아무것도 들지 않은 상태로 청소를 시작함."
    },
    {
      "id": "R3",
      "summary_ko": "도구 없이 청소를 시작하며 손에서 세정액 자국이 남음."
    },
    {
      "id": "R4",
      "summary_ko": "창문을 닦는 동작으로 전환되면서 손이 길어지고 기괴하게 변함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "창문을 닦기 위해 이동하는 동안 유리잔이 반투명한 큰 걸레나 가방으로 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "참조 설명은 유리잔이 사라진다고 기술한 반면, 후보 설명은 유리잔이 청소 도구/걸레로 변형된다고 설명하여 사라짐과 변형의 관점 차이가 있어 동일성 여부가 불확실함."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "참조 설명은 유리잔이 아무것으로도 대체되지 않고 맨손으로 닦기 시작한다고 명시했으나, 후보 설명은 유리잔이 청소용 걸레/가방으로 변형되었다고 기술하여 상반됨."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "참조 설명은 도구 없이 맨손으로 닦으며 세정액 자국이 남는 현상을 다루지만, 후보 설명은 유리잔이 걸레로 변형되는 현상을 기술하여 대상과 오류 내용이 다름."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "손이 비정상적으로 길어지는 왜곡을 설명한 참조 설명과 유리잔이 걸레로 변형되는 후보 설명은 전혀 다른 현상을 다룸."
    }
  ]
}
